import subprocess

def filtered(files):
    out = []
    for f in files:
        diff = subprocess.run(['git','diff','-U3','--',f],capture_output=True,text=True).stdout
        lines = diff.split('\n')
        header, hunks, cur = [], [], []
        for ln in lines:
            if ln.startswith('@@'):
                if cur: hunks.append(cur)
                cur = [ln]
            elif hunks or cur:
                cur.append(ln)
            else:
                header.append(ln)
        if cur: hunks.append(cur)
        keep = [h for h in hunks if not any('MergeTreeDataPartState::' in l for l in h)]
        if keep:
            out.append('\n'.join(header + [l for h in keep for l in h]))
    return '\n'.join(out)

